using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using CrystalParkour;using FirstPerson;
public static class TraversalV2Scenarios
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Call(object o,string name)=>o.GetType().GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance)?.Invoke(o,null);
 static void Input(FirstPersonInput input,string name,object value)=>typeof(FirstPersonInput).GetProperty(name).SetValue(input,value);
 public static object Run()
 {
  Check(!Application.isPlaying,"Edit Mode required");var previous=SceneManager.GetActiveScene();var s=EditorSceneManager.OpenScene(CrystalParkour.Editor.CrystalTraversalLabBuilder.ScenePath,OpenSceneMode.Additive);SceneManager.SetActiveScene(s);
  var roots=s.GetRootGameObjects();foreach(var r in roots)r.transform.position+=Vector3.right*1000;
  var p=roots.First(g=>g.GetComponent<CrystalTraversal>()).GetComponent<CrystalTraversal>();var motor=p.motor;var combat=p.combat;var input=motor.input;var cases=new List<string>();var metrics=new Dictionary<string,object>();var winds=roots.SelectMany(g=>g.GetComponentsInChildren<WindVolume>(true)).ToArray();WindVolume testWind=null;
  try
  {
   Call(motor,"Awake");Call(p.GetComponent<FirstPersonVitals>(),"Awake");Call(combat,"Awake");Call(combat.actions.motion,"Awake");Call(p,"Awake");Call(p,"OnEnable");foreach(var w in winds){Call(w,"Awake");Call(w,"OnEnable");}
   void Place(Vector3 pos){p.Drop("Validation");motor.Body.enabled=false;p.transform.position=pos;motor.Body.enabled=true;motor.SetLookRotation(Quaternion.identity);motor.StopMomentum();motor.WindTargetVelocity=Vector3.zero;Input(input,"Move",Vector2.zero);Input(input,"Look",Vector2.zero);Input(input,"JumpPressed",false);Physics.SyncTransforms();}
   var wgo=new GameObject("Isolated wind",typeof(BoxCollider),typeof(WindVolume));wgo.transform.position=new Vector3(400,100,400);wgo.GetComponent<BoxCollider>().size=Vector3.one*100;testWind=wgo.GetComponent<WindVolume>();testWind.gravityScale=.42f;Call(testWind,"Awake");Call(testWind,"OnEnable");
   Place(wgo.transform.position);Input(input,"Move",Vector2.right);p.Tick(.25f,false);for(int i=0;i<60;i++)motor.Tick(1f/60);Check(motor.ControlVelocity.x>5&&p.transform.position.x>404,"Updraft erased horizontal WASD");Check(motor.Velocity.y<-7&&motor.Velocity.y>-10,"Updraft did not retain falling acceleration");metrics["verticalWindAfter1sec"]=motor.Velocity.y;cases.Add("Real motor input moves horizontally in vertical wind; gravity remains negative");
   var duplicate=UnityEngine.Object.Instantiate(wgo);var duplicateWind=duplicate.GetComponent<WindVolume>();Call(duplicateWind,"Awake");Call(duplicateWind,"OnEnable");var sample=WindVolume.Evaluate(wgo.transform.position,1);Check(Mathf.Abs(sample.gravityScale-.42f)<.001f,"Overlapping updrafts accumulated into levitation");Call(duplicateWind,"OnDisable");UnityEngine.Object.DestroyImmediate(duplicate);cases.Add("Overlapping vertical winds retain 42% gravity rather than cancelling it");
   testWind.kind=WindKind.HorizontalAirflow;testWind.direction=Vector3.left;testWind.driftSpeed=6;testWind.responseAcceleration=4;Place(wgo.transform.position);Input(input,"Move",Vector2.up);p.Tick(.25f,false);for(int i=0;i<60;i++)motor.Tick(1f/60);Check(motor.ControlVelocity.z>5&&motor.WindVelocity.x<-3.8f&&p.transform.position.z>404,"Horizontal airflow consumed perpendicular steering");metrics["crosswindControl"]=motor.ControlVelocity.ToString();metrics["crosswindDrift"]=motor.WindVelocity.ToString();cases.Add("Horizontal airflow adds drift while perpendicular WASD remains available");
   foreach(var w in winds.Where(w=>w.kind==WindKind.GravityRelief)){Check(w.StrengthAt(1-w.phaseOffset)>.99f&&w.StrengthAt(6-w.phaseOffset)==0,"Pulse valve timing wrong");Check(w.gravityScale>=.2f&&w.gravityScale<1,"Invalid remaining gravity");}
   Call(testWind,"OnDisable");UnityEngine.Object.DestroyImmediate(wgo);testWind=null;cases.Add("Both silo valves have real timed off windows");
   var surfaces=roots.SelectMany(r=>r.GetComponentsInChildren<CrystalSurface>(true)).ToArray();Check(surfaces.All(c=>winds.All(w=>!w.Contains(c.transform.position))),"Crystal parkour intersects a wind field");Check(winds.Count(w=>w.kind==WindKind.GravityRelief)==2&&winds.Count(w=>w.kind==WindKind.HorizontalAirflow)==3,"Wrong number of wind modules");cases.Add("All crystal surfaces lie outside the two updrafts and three horizontal wind volumes");
   var jumpResults=new List<object>();
   foreach(var silo in roots.Where(r=>r.name.Contains("Pulse Silo")))
   {
    var ledges=silo.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Safe ledge ")).OrderBy(t=>int.Parse(t.name.Substring(11))).ToArray();
    for(int i=0;i<ledges.Length-1;i++)
    {
     var from=ledges[i].position;var target=ledges[i+1].position;Place(from+Vector3.up*.08f);motor.GravityScale=.42f;motor.Body.Move(Vector3.down*.15f);Input(input,"JumpPressed",true);
     bool landed=false;float peak=from.y;var trajectory=new List<object>();
     for(int f=0;f<220;f++)
     {
      var d=Vector3.ProjectOnPlane(target-p.transform.position,Vector3.up);var steering=Vector3.ClampMagnitude(d*3.5f/motor.airSpeed,1);Input(input,"Move",new Vector2(steering.x,steering.z));motor.Tick(1f/120);Input(input,"JumpPressed",false);peak=Mathf.Max(peak,p.transform.position.y);
      if(f%12==0)trajectory.Add(new{f,pos=p.transform.position.ToString("F3"),velocity=motor.Velocity.ToString("F3"),ground=motor.Body.isGrounded});
      if(f>50&&motor.Body.isGrounded&&Mathf.Abs(p.transform.position.y-target.y)<.25f&&d.magnitude<1){landed=true;break;}
     }
     jumpResults.Add(new{silo=silo.name,from=i+1,to=i+2,landed,peakRise=peak-from.y});if(!landed)File.WriteAllText("Docs/CrystalParkour/V2/Validation/JumpDebug.json",Newtonsoft.Json.JsonConvert.SerializeObject(trajectory,Newtonsoft.Json.Formatting.Indented));Check(landed,"Silo jump not reachable: "+silo.name+" "+(i+1)+" -> "+(i+2)+" actual="+p.transform.position+" target="+target+" peak="+(peak-from.y));
    }
   }
   metrics["siloJumps"]=jumpResults;Check(Mathf.Sqrt(44)*Mathf.Sqrt(44)/(40*.42f)>2.5f,"Jump model unexpected");cases.Add("All consecutive silo ledges are reachable with the actual CharacterController under active wind");
   var drones=roots.SelectMany(r=>r.GetComponentsInChildren<TraversalDrone>()).ToArray();Check(drones.Length==3,"Missing descending drones");
   foreach(var d in drones){Check(d.route==DroneRoute.DescendingStream,"Drone still shuttles horizontally");var top=d.PositionAt(-d.phaseOffset+.1,out bool v1);var bottom=d.PositionAt(-d.phaseOffset+9.8,out bool v2);Check(v1&&v2&&bottom.y<top.y-13&&Mathf.Abs(top.x-bottom.x)<.001f&&Mathf.Abs(top.z-bottom.z)<.001f,"Route is not strictly descending");d.PositionAt(-d.phaseOffset+11,out bool hidden);Check(!hidden,"Drone does not hide for recycle");}
   Check(Mathf.Abs(drones[1].phaseOffset-drones[0].phaseOffset-4)<.01f&&Mathf.Abs(drones[2].phaseOffset-drones[1].phaseOffset-4)<.01f,"Drone stream not phased");
   var drone=drones[0];drone.Tick(0,2);Call(drone,"Start");var deck=drone.deck.bounds;Place(new Vector3(deck.center.x+.8f,deck.max.y+.02f,deck.center.z));var before=p.transform.position;drone.Tick(.1f,2.1);Check(p.RodeDrone&&p.transform.position.y<before.y-.02f&&Mathf.Abs(p.transform.position.x-before.x)<.01f,"Descending deck carry: before="+before+" after="+p.transform.position+" rode="+p.RodeDrone+" deck="+drone.deck.bounds);before=p.transform.position;drone.Tick(.1f,12.1);Check(Vector3.Distance(before,p.transform.position)<.01f,"Drone respawn teleported its rider to the top");cases.Add("Three phased drones descend, carry riders down and recycle without teleporting the rider");
   var growth=roots.SelectMany(r=>r.GetComponentsInChildren<CrystalGrowthSite>()).First(g=>g.wallGrowth);Call(growth,"Awake");Check(!growth.growthRoot.activeSelf,"Remote anchor visible before activation");var anchor=growth.growthRoot.GetComponent<CrystalSurface>();Call(anchor,"Awake");Check(!anchor.ActionTargetAlive,"Remote anchor can be tethered before growth");
   var marker=growth.strikeCollider.bounds.center;var normal=growth.transform.up;Place(marker+normal*1.3f-Vector3.up*1.6f);motor.SetLookRotation(Quaternion.LookRotation(-normal));combat.Cancel();p.Tick(.6f,false);Physics.SyncTransforms();combat.Press();combat.Release();combat.Tick(.02f);Check(!growth.HasGrown,"Wall growth happened during punch wind-up");combat.Tick(.2f);Check(growth.HasGrown&&p.GrewWall,"Wall marker did not receive native gauntlet hit");Check(!anchor.ActionTargetAlive,"Remote anchor available while still growing");growth.Tick(growth.duration);Check(anchor.ActionTargetAlive&&growth.Finished,"Finished remote anchor did not become usable");metrics["remoteGrowthDistance"]=Vector3.Distance(marker,anchor.transform.position);Check((float)metrics["remoteGrowthDistance"]>10,"Growth target was not remote");cases.Add("A real hit on the wall marker grows a remote anchor; tether is gated until completion");
   motor.SetLookRotation(Quaternion.LookRotation(anchor.contact.bounds.center-p.aim.position));Physics.SyncTransforms();Check(p.TryFindSurface(out var anchorHit,out var foundAnchor)&&foundAnchor==anchor,"Grown anchor is not reachable from the strike spur");combat.Cancel();combat.Press();combat.Tick(.5f);Check(p.BeginTether(anchor,anchorHit.point,anchorHit.normal),"Tether failed on actual crystal mesh");for(int f=0;f<35&&p.State==CrystalTraversal.Mode.Pulling;f++)p.Tick(.05f,true);Check(p.State==CrystalTraversal.Mode.Attached,"Mesh tether cannot reach contact");int rebounds=p.Rebounds;combat.Release();for(int f=0;f<24&&p.Rebounds==rebounds;f++)combat.Tick(1f/120);Check(p.Rebounds==rebounds+1,"Native hitbox cannot hit the visible crystal contact mesh");cases.Add("The newly grown crystal can actually be pulled to and rebounded from using native animation hitboxes");
   var variants=Directory.GetFiles("Assets/Game/Environment/crystal/Prefabs/V2","*.prefab");Check(variants.Length==12,"Missing crystal variants");foreach(var file in variants){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(file);Check(asset.transform.localRotation==Quaternion.identity,"Crystal prefab root has unnormalized FBX axes");Check(asset.GetComponentsInChildren<Renderer>().All(r=>r.sharedMaterials.All(m=>m&&m.shader.name=="NullBoundary/Crystal Facet")),"Lost crystal material");}
   var groundPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(variants.First(f=>f.Contains("05_Ground")));var instance=UnityEngine.Object.Instantiate(groundPrefab);var b=instance.GetComponentInChildren<Renderer>().bounds;Check(b.size.y>b.size.z*.6f&&b.max.y>1,"Ground crystal points along wrong Unity axis");UnityEngine.Object.DestroyImmediate(instance);cases.Add("Twelve imported crystal prefabs preserve the facet shader and normalize FBX coordinates through a wrapper");
   var result=new{passed=true,cases=cases.ToArray(),metrics};File.WriteAllText("Docs/CrystalParkour/V2/Validation/V2MechanicReport.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
  }
  finally{foreach(var w in winds)if(w)Call(w,"OnDisable");if(testWind){Call(testWind,"OnDisable");UnityEngine.Object.DestroyImmediate(testWind.gameObject);}p.Drop("End validation");Call(p,"OnDisable");combat.Cancel();combat.actions.motion.ReleaseGraph();SceneManager.SetActiveScene(previous);EditorSceneManager.CloseScene(s,true);}
 }
}
